#!/usr/bin/env python3
"""Отчёт: суммарная статистика и выводы → out/report/ОТЧЁТ.md и report.html (картинки внутри). Все числа берутся из data/stats.json,
data/sensitivity.json и заполненных форм; формулировки выводов проверяют условия (если данные не подтверждают — вывод смягчается или не пишется).
Запуск: python3 tools/playtest/write_report.py"""
import json,os,base64,collections,re,math
HERE=os.path.dirname(os.path.abspath(__file__));D=os.path.join(HERE,'data');OUT=os.path.join(HERE,'out','report');CH=os.path.join(OUT,'charts')
J=lambda p:json.load(open(p,encoding='utf-8'))
S=J(os.path.join(D,'stats.json'));cat=J(os.path.join(HERE,'levels_catalog.json'));prof=J(os.path.join(D,'level_profiles.json'))
SENS=J(os.path.join(D,'sensitivity.json')) if os.path.exists(os.path.join(D,'sensitivity.json')) else None
roster=J(os.path.join(D,'roster.json'));sessions=J(os.path.join(D,'sessions.json'))
forms={}
for f in os.listdir(os.path.join(HERE,'out','forms')):
    if f.endswith('.json'):
        d=J(os.path.join(HERE,'out','forms',f));forms[d['respondent']['id']]=d
GR=['7-8','9-10','11-13','14+'];GL={'7-8':'7–8 лет','9-10':'9–10 лет','11-13':'11–13 лет','14+':'14+ и взрослые'}
GLG={'7-8':'7–8 лет','9-10':'9–10 лет','11-13':'11–13 лет','14+':'14+ и взрослых'}
NM=lambda lv:cat[lv]['name']
mean=lambda a:sum(a)/len(a) if a else None
def f1(x,n=1):
    if x is None: return '—'
    return (f'{x:.{n}f}').replace('.',',')
def pct(x): return '—' if x is None else f'{round(100*x)}%'
def plural(n,forms):
    n=int(round(n));m=n%100
    if 11<=m<=14: return forms[2]
    return forms[0] if n%10==1 else forms[1] if 2<=n%10<=4 else forms[2]
def tbl(head,rows):
    out='| '+' | '.join(head)+' |\n|'+'|'.join(['---']*len(head))+'|\n'
    for r in rows: out+='| '+' | '.join(str(c) for c in r)+' |\n'
    return out
def nps(g):
    v=[f['answers']['nps'] for f in forms.values() if f['respondent']['group']==g and 'nps' in f['answers']]
    if not v: return None
    return round(100*(sum(1 for x in v if x>=9)-sum(1 for x in v if x<=6))/len(v)),round(mean(v),1),len(v)
def short(k,n=58):
    k=re.split(r' \(',k)[0]
    return k if len(k)<=n else k[:n-1]+'…'
def top(dist,n=4): return ', '.join(f'{k} ({v})' for k,v in list(dist.items())[:n]) if dist else '—'
sv=S['survey'];R=S['reading'];tl=S['levels_table']
def wrank(lv): return 1+sum(1 for k,v in tl.items() if v['words']>tl[lv]['words'])
L=[]
w=L.append

# ============================================================================== вводная
w('# Симулированный плейтест «Златой цепи» (final06): суммарная статистика и выводы\n')
w('> **Это симуляция, а не исследование с людьми.** Ни один ответ не принадлежит живому человеку. Боты играют в настоящую игру, но то, как люди читают, понимают, злятся и что любят, — допущения модели.\n'
  '> Каждая цифра ниже помечена базой: **[ДВИЖОК]** — измерено ботами в игре (бой, тексты и число задач, ролики, подсказки); **[МОДЕЛЬ]** — посчитано по допущениям о возрасте (`method/personas.json`); '
  '**[ПЕРСОНА]** — ответ симулированного респондента в опросе (вкус, «любимое» — случайны по чертам персоны и популярностью не являются). Выводы — гипотезы для живого плейтеста (чек-лист в конце).\n')
n=S['n']
w(f"**Что сделано.** 36 уровней игры прошли существующие боты-«оракулы» с телеметрией (идеальная игра: что и в каком объёме показывает каждый уровень). Затем {n['respondents']} симулированных респондентов — "
  f"**{n['pairs']} пар ({n['pairs']*2} человек) и {n['solo']} одиночек** в четырёх возрастных группах — прошли кампанию уровень за уровнем: все встречи с мороками — боевыми ботами с возрастными реакциями "
  f"в настоящем движке; чтение, понимание задач, застревание, парная работа, ритм и усталость — моделью. По итогам каждый «человек» заполнил **свой** опросник — четыре присланные формы, открытые и заполненные в браузере штатным способом "
  f"(формат `zc-opros-v1`, поле `simulated: true`).\n")
w(tbl(['Группа','Респондентов','Вдвоём / один','Кто играл'],[
 [GL['7-8'],n['by_group']['7-8'],f"{n['by_group_mode']['7-8']['pair']} / {n['by_group_mode']['7-8']['solo']}",'ребёнок + родитель (2), + старший брат/сестра, + друг (2), один'],
 [GL['9-10'],n['by_group']['9-10'],f"{n['by_group_mode']['9-10']['pair']} / {n['by_group_mode']['9-10']['solo']}",'ребёнок + родитель, два друга, ребёнок + старший брат, один'],
 [GL['11-13'],n['by_group']['11-13'],f"{n['by_group_mode']['11-13']['pair']} / {n['by_group_mode']['11-13']['solo']}",'брат/сестра младших, два друга, ребёнок + родитель, двое одиночек'],
 [GL['14+'],n['by_group']['14+'],f"{n['by_group_mode']['14+']['pair']} / {n['by_group_mode']['14+']['solo']}",'4 родителя с детьми 7–13, два друга (подросток + взрослый), профессиональный тестировщик']]))
w('')
# ============================================================================== что главное
w('## 1. Главное в десяти строках\n')
hots={g:S['hot'][g] for g in GR}
allhot=collections.Counter(lv for g in GR for lv,_,_ in hots[g][:3])
first_hot=allhot.most_common(1)[0][0]
FP=S['F_parts']
barrier_young=FP['7-8']['stuck']+FP['7-8']['unread']>=0.5 and FP['9-10']['stuck']>=0.5
w(f"1. **[ДВИЖОК+МОДЕЛЬ] {'Задачи — главный барьер для 7–10 лет, а не бой.' if barrier_young else 'Задачи и бой — два главных барьера для 7–10 лет.'}** На непонимание задач и ожидание подсказки приходится {pct(FP['7-8']['stuck']+FP['7-8']['unread'])} «досады» у 7–8 лет и {pct(FP['9-10']['stuck'])} у 9–10 (остальное — бой). Средняя задача уровня — {f1(R['words_mean'])} слова, {R['gt20']} из {R['total_obj']} ({pct(R['gt20']/R['total_obj'])}) длиннее 20 слов; "
  f"семилетка за 15 секунд прочтёт около {f1(15*3.0/6.5,0)} слов. Голосом озвучена {S['voice']['tasks_voiced']} задача из {S['voice']['tasks']} (озвучка игры — реплики персонажей); "
  f"системное чтение вслух есть только в прологе и мире 1 ({R['kids_obj']} из {R['all_obj']} задач, {pct(R['kids_obj']/R['all_obj'])}) и только если в ОС есть русский голос. "
  f"В модели 7–8 лет понимают с первого раза {pct(S['understood']['7-8'])} задач (9–10 — {pct(S['understood']['9-10'])}, 14+ — {pct(S['understood']['14+'])}) и тратят на «застрял» {f1(S['stuck_min_lvl']['7-8'])} мин на уровень против {f1(S['stuck_min_lvl']['14+'],2)} у взрослых.")
ab=S.get('ab',{})
def abtxt():
    parts=[];ratios=[]
    for g,a in ab.items():
        kk=[k for k in a if k.startswith('детские')][0];nk=[k for k in a if k.startswith('обычные')][0]
        ratios.append(a[nk]['hits_per_fight']/max(0.01,a[kk]['hits_per_fight']))
        parts.append(f"{GL[g]}: попаданий по герою за встречу {f1(a[kk]['hits_per_fight'],2)} → {f1(a[nk]['hits_per_fight'],2)}, падений {f1(a[kk]['downs_per_fight'],2)} → {f1(a[nk]['downs_per_fight'],2)}, выиграно за минуту {pct(a[kk]['clear'])} → {pct(a[nk]['clear'])}")
    return '; '.join(parts),ratios
if ab:
    abs_,ratios=abtxt();ratio=mean(ratios)
    w(f"2. **[ДВИЖОК] Детские настройки обрываются на границе мира 1 → 2.** Опыт «те же дети — те же встречи» (умения фиксированы; арена мира 1 с детскими настройками против арены мира 2 без них): {abs_} "
      f"(стрелка — от детских настроек к обычным; в среднем в {f1(ratio,1)} раза больше попаданий). Настройки включены в `FIN.kids.worlds=[1]` и только для пролога и мира 1.")
else:
    w('2. **[ДВИЖОК] Детские настройки (замах 0,9 с, окно отбива 0,40 с, подсказки втрое дольше, чтение задач вслух) включены только в прологе и мире 1.** В мирах 2–5 — стандартные окна.')
sp=sorted(((g,S['hot'][g][0]) for g in GR),key=lambda x:-x[1][1])
ranks={g:[lv for lv,_,_ in hots[g]].index(first_hot)+1 if first_hot in [lv for lv,_,_ in hots[g]] else None for g in GR}
rk_txt='первый по трудности у '+', '.join(GLG[g] for g in GR if ranks[g]==1)+('; второй — у '+', '.join(GLG[g] for g in GR if ranks[g]==2) if any(ranks[g]==2 for g in GR) else '')+('; ниже шестого места — у '+', '.join(GLG[g] for g in GR if ranks[g] is None) if any(ranks[g] is None for g in GR) else '')
w(f"3. **[МОДЕЛЬ+ДВИЖОК] Первая «стена» — {first_hot} «{NM(first_hot)}»** ({tl[first_hot]['n_obj']} задач, {tl[first_hot]['words']} {plural(tl[first_hot]['words'],('слово','слова','слов'))}, парных задач — {tl[first_hot]['coop_obj']}, "
  f"встреч с мороками — {tl[first_hot]['enc']}): {rk_txt}. Следом — "
  + ', '.join(f"{lv} «{NM(lv)}»" for lv,c in allhot.most_common(5)[1:4])+'.')
pl=S['plan'];tu=S['tutorial']
w(f"4. **[ДВИЖОК+МОДЕЛЬ] Для 7–8 лет бой упирается во внимание и время реакции.** Из замахов морок {pct(pl['7-8']['late']+pl['7-8']['lapse'])} не замечены или замечены поздно (у 14+ — {pct(pl['14+']['late']+pl['14+']['lapse'])}); "
  f"отбить пытаются в {pct(pl['7-8']['parry_try'])} замахов (у 14+ — {pct(pl['14+']['parry_try'])}), кувырок на красный — в {pct(pl['7-8']['roll_try'])}. Учебный бой пролога у семилетки идёт ~{f1(tu['7-8']['sec'],0)} с на одного морока ({f1(tu['7-8']['hits'],1)} попадания по нему) против ~{f1(tu['14+']['sec'],0)} с у взрослого.")
sg=S['solo_vs_pair']
w(f"5. **[МОДЕЛЬ] Парные задачи плохо переносятся на одиночку и на детей без взрослого.** В игре {R['coop_total']} задач с «вместе/оба/все четверо» и {R['swap_total']} с переключением героя; "
  f"в симуляции «один» тратит на застревание {f1(sg['solo']['stuck_min_lvl'],2)} мин на уровень против {f1(sg['pair']['stuck_min_lvl'],2)} у пар (малая выборка: {n['solo']} одиночек).")
qn={g:S['quit_levels'][g] for g in GR}
w(f"6. **[МОДЕЛЬ] До конца игры в симуляции доходят: {', '.join(f'{GL[g]} — {pct(S['completion'][g])}' for g in GR)}.** Уходят чаще на уровнях мира 2–3 (подробнее в разделе 3). Среднее время игры — {f1(mean(list(S['hours'].values())),1)} ч.")
w(f"7. **[ДВИЖОК] Ролики — {f1(R['cine_sec_total']/60,0)} {plural(R['cine_sec_total']/60,('минута','минуты','минут'))} по профилям уровней** (в финале с Кощеем — десятки обучающих сцен), пропустить можно только вдвоём (удерживая прыжок) — в одиночку и для ребёнка, которому надоело, это неудобно.")
w(f"8. **[МОДЕЛЬ] Взрослым и подросткам (14+) на Среднем пути в среднем легко:** {f1(S['downs_lvl']['14+'],2)} падения на уровень, воспринимаемая трудность {f1(S['diff']['14+'],1)} из 5; игра остаётся семейной, но «Богатырский» путь для опытных стоит явнее предлагать.")
w(f"9. **[ПЕРСОНА] Опросы ожидаемо следуют телеметрии:** средняя оценка игры — {', '.join(f'{GL[g]}: {f1(sv[g]['stars'][0],1)}' for g in GR)} (из 5). Ответы про вкус — случайны по чертам персон; главное в них — связь «где трудно ↔ что ругают».")
w("10. **Положительное.** Бой читаем для 11+ (сигналы понятны), ритм-уровни не блокируют (промахов по доле мало на детском и среднем пути), хаб (Лукоморье) в моделях любят, кооператив даёт ролям дополнять друг друга. Детали — в разделе 7.\n")

