import markdown
def inline(m):
    p=os.path.join(OUT,m.group(2))
    if not os.path.exists(p): return m.group(0)
    return f'![{m.group(1)}](data:image/png;base64,{base64.b64encode(open(p,"rb").read()).decode()})'
html_md=re.sub(r'!\[([^\]]*)\]\((charts/[^)]+)\)',inline,md)
body=markdown.markdown(html_md,extensions=['tables','sane_lists'])
css='''<style>:root{color-scheme:light dark;--bg:#fcfcfb;--ink:#1f1d1a;--muted:#5d5a54;--line:#e6e3dc;--acc:#2a5db0;--card:#f4f2ec}
@media (prefers-color-scheme:dark){:root{--bg:#1a1a19;--ink:#f1efe8;--muted:#b9b6ac;--line:#38362f;--acc:#7fa9ec;--card:#24231f}}
body{background:var(--bg);color:var(--ink);font:16px/1.55 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;margin:0}
main{max-width:920px;margin:0 auto;padding:24px 16px 80px}h1{font-size:1.7rem}h2{margin-top:2.2rem;border-bottom:2px solid var(--line);padding-bottom:.2rem}h3{margin-top:1.6rem}
blockquote{background:var(--card);border-left:4px solid var(--acc);margin:1rem 0;padding:.6rem 1rem;color:var(--muted)}img{max-width:100%;height:auto;border-radius:6px}
table{border-collapse:collapse;width:100%;font-size:.88rem;display:block;overflow-x:auto}th,td{border:1px solid var(--line);padding:.35rem .5rem;text-align:left;vertical-align:top}th{background:var(--card)}code{background:var(--card);padding:0 .25rem;border-radius:3px}</style>'''
open(os.path.join(OUT,'report.html'),'w',encoding='utf-8').write(f'<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Симулированный плейтест Златой цепи</title>{css}</head><body><main>{body}</main></body></html>')
